-- Dos parciales recibidos en imágenes. Las consignas se transcriben; la pregunta B10 no muestra opciones en la foto.
begin;
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 1$cbc$,$cbc$<p>Una crema humectante contiene 0,180% en masa de vitamina A. Si la dosis tóxica de vitamina A para un niño de 20,0 kg es de 60,0 mg, ¿qué masa de crema, expresada en g, puede usarse como máximo para humectar la piel del niño?</p>$cbc$,'Parcial A · fotografía recibida',10,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>Convertí la masa de vitamina A a gramos y el porcentaje a fracción másica.</p><div class="u6Equation"><span class="u6Math" data-latex="60%2C0%5C%2C%5Cmathrm%7Bmg%7D%3D0%2C0600%5C%2C%5Cmathrm%7Bg%7D%3B%5Cqquad%200%2C180%5C%25%3D0%2C00180" data-display="true"></span></div></div></div><div class="u6Step"><span>2</span><div><p>La dosis ya está dada para ese niño; los 20,0 kg no se multiplican otra vez.</p><div class="u6Equation"><span class="u6Math" data-latex="m_%7B%5Cmathrm%7Bcrema%7D%7D%3D%5Cfrac%7B0%2C0600%5C%2C%5Cmathrm%7Bg%7D%7D%7B0%2C00180%7D%3D33%2C3%5C%2C%5Cmathrm%7Bg%7D" data-display="true"></span></div></div></div>$cbc$,$cbc$<p>33,3 g de crema como máximo.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 2$cbc$,$cbc$<p>Dados los elementos ⁸⁷D y Z, se sabe que:</p><ul><li>El catión divalente de ⁸⁷D es isoelectrónico con el kriptón</li><li>Z es isóbaro con ⁵⁷₂₆Fe</li></ul><p>a) Identificar al nucleido ⁸⁷D (identificando el símbolo químico); b) Sabiendo que el catión Z²⁺ posee 25 electrones, indicar el número de neutrones que tiene Z.</p>$cbc$,'Parcial A · fotografía recibida',20,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<details class="u6Subsolution"><summary>a) Identificar D</summary><div><p>Kr tiene 36 electrones. Si D²⁺ tiene 36, el átomo neutro tiene 38 protones: es estroncio.</p><div class="u6Equation"><span class="u6Math" data-latex="Z_D%3D36%2B2%3D38%5Cquad%5CRightarrow%5Cquad%7B%7D%5E%7B87%7D_%7B38%7D%5Cmathrm%7BSr%7D" data-display="true"></span></div></div></details><details class="u6Subsolution"><summary>b) Neutrones de Z</summary><div><p>Z²⁺ tiene 25 electrones, por lo que Z neutro tiene 27 protones (Co). Ser isóbaro de ⁵⁷₂₆Fe fija A = 57, sin fijar su Z.</p><div class="u6Equation"><span class="u6Math" data-latex="N%3DA-Z%3D57-27%3D30" data-display="true"></span></div></div></details>$cbc$,$cbc$<p>a) ⁸⁷₃₈Sr; b) Z tiene 30 neutrones.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 3$cbc$,$cbc$<p>Complete el enunciado con la palabra correcta: El número de electrones en el último nivel determina el ............ en el que se ubica el elemento en la tabla periódica.</p>$cbc$,'Parcial A · fotografía recibida',30,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Idea</span><div><p>En los elementos representativos, el número de electrones de valencia permite ubicar el grupo o familia: por ejemplo, siete electrones de valencia indican el grupo 17.</p></div></div>$cbc$,$cbc$<p>grupo.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 4$cbc$,$cbc$<p>Ordenar los siguientes elementos según energía de primera ionización creciente:<br>i. Primer calcógeno<br>ii. Tercer calcógeno<br>iii. Tercer metal alcalinotérreo</p>$cbc$,'Parcial A · fotografía recibida',40,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>Primer calcógeno: O; tercer calcógeno: Se; tercer alcalinotérreo: Sr.</p></div></div><div class="u6Step"><span>2</span><div><p>La energía de ionización disminuye hacia abajo en un grupo y aumenta, en general, hacia la derecha en un período.</p><div class="u6Equation"><span class="u6Math" data-latex="%5Cmathrm%7BSr%7D%3C%5Cmathrm%7BSe%7D%3C%5Cmathrm%7BO%7D" data-display="true"></span></div></div></div>$cbc$,$cbc$<p>iii &lt; ii &lt; i (Sr &lt; Se &lt; O).</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 5$cbc$,$cbc$<p>Dibujar una estructura de Lewis para el SCl₂.</p>$cbc$,'Parcial A · fotografía recibida',50,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>Total: 6 electrones de S + 2 × 7 de Cl = 20 electrones de valencia.</p></div></div><div class="u6Step"><span>2</span><div><p>Trazá Cl–S–Cl (4 electrones). Cada Cl recibe tres pares libres (12 electrones); los cuatro restantes forman dos pares libres en S. Todos completan el octeto.</p></div></div><div class="u6Equation"><span class="u6Math" data-latex="%5Cmathrm%7BCl-S-Cl%7D%5Cqquad%28S%3A%5C%202%5C%20pares%5C%20libres%3B%5C%20cada%5C%20Cl%3A%5C%203%29" data-display="true"></span></div>$cbc$,$cbc$<p>Cl–S–Cl con dos pares libres en S y tres en cada Cl.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 6$cbc$,$cbc$<p>Indicar cuál de los siguientes enunciados corresponde al H₂SO₄: (i) el H presenta estado de oxidación +2; (ii) es un compuesto predominantemente iónico; (iii) está formado por moléculas triatómicas; (iv) su nombre es hidróxido de azufre (VI); (v) es un oxoácido.</p>$cbc$,'Parcial A · fotografía recibida',60,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Descartar</span><div><p>H tiene +1, la molécula es covalente y contiene siete átomos (2 H + 1 S + 4 O). Su nombre es ácido sulfúrico.</p></div></div><div class="u6Step"><span>Elegir</span><div><p>Contiene H, O y un elemento central (S): pertenece a los oxoácidos.</p></div></div>$cbc$,$cbc$<p>(v) es un oxoácido.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 7$cbc$,$cbc$<p>Dados las siguientes especies, indicar cuál presenta geometría triangular y es no polar:</p><ol type="i"><li>H₂CO (estructura de Lewis en la foto)</li><li>SO₃ (estructura de Lewis en la foto)</li><li>NH₃ (estructura de Lewis en la foto)</li><li>SeO₂ (estructura de Lewis en la foto)</li></ol><p class="examSourceLink"><a href="./assets/chemistry/parciales/parcial-a.png" target="_blank" rel="noopener">Ver fotografía original del parcial ↗</a></p>$cbc$,'Parcial A · fotografía recibida',70,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>SO₃ tiene tres regiones enlazantes alrededor de S y ningún par libre sobre el átomo central en la representación TRePEV: AX₃, trigonal plana.</p></div></div><div class="u6Step"><span>2</span><div><p>Los tres enlaces S–O son equivalentes por resonancia y sus dipolos se cancelan por simetría. H₂CO es trigonal pero polar; NH₃ es piramidal y SeO₂ es angular.</p></div></div>$cbc$,$cbc$<p>ii) SO₃.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 8$cbc$,$cbc$<p>Una muestra de un metal puro tiene una masa de 15,2 g y contiene 8,47×10²² átomos. Determinar la masa correspondiente a 0,375 mol de dicho metal.</p>$cbc$,'Parcial A · fotografía recibida',80,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>Pasá los átomos de la muestra a moles, usando Nₐ = 6,02×10²³ mol⁻¹.</p><div class="u6Equation"><span class="u6Math" data-latex="n%3D%5Cfrac%7B8%2C47%5Ctimes10%5E%7B22%7D%7D%7B6%2C02%5Ctimes10%5E%7B23%7D%7D%3D0%2C1407%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></span></div></div></div><div class="u6Step"><span>2</span><div><p>Calculá la masa molar y luego la masa pedida.</p><div class="u6Equation"><span class="u6Math" data-latex="M%3D%5Cfrac%7B15%2C2%5C%2C%5Cmathrm%7Bg%7D%7D%7B0%2C1407%5C%2C%5Cmathrm%7Bmol%7D%7D%5Capprox108%5C%2C%5Cmathrm%7Bg%2Fmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="m%3D0%2C375%5C%2C%5Cmathrm%7Bmol%7D%5Ctimes108%5C%2C%5Cmathrm%7Bg%2Fmol%7D%3D40%2C5%5C%2C%5Cmathrm%7Bg%7D" data-display="true"></span></div></div></div>$cbc$,$cbc$<p>40,5 g.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 9$cbc$,$cbc$<p>Se tienen las siguientes muestras. Muestra A: desflurano (C₃H₂F₆O), densidad = 1,68 g/L, contiene 9,00×10²³ átomos de F. Muestra B: sevoflurano (C₄H₃F₇O), densidad = 1,90 g/L, contiene 8,00×10²³ átomos de F. ¿Cuál de las dos muestras ocupa un menor volumen? Justificar al dorso indicando detalladamente todos los cálculos.</p>$cbc$,'Parcial A · fotografía recibida',90,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p>Cada molécula A contiene 6 F y cada molécula B contiene 7 F. Dividí la cantidad de átomos de F por ese subíndice para obtener moléculas, y luego por Nₐ para obtener moles. Usá C=12, H=1, F=19, O=16 g/mol.</p><details class="u6Subsolution"><summary>Muestra A · desflurano</summary><div><div class="u6Equation"><span class="u6Math" data-latex="M_A%3D3%2812%29%2B2%281%29%2B6%2819%29%2B16%3D168%5C%2C%5Cmathrm%7Bg%2Fmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="n_A%3D%5Cfrac%7B9%2C00%5Ctimes10%5E%7B23%7D%7D%7B6%286%2C02%5Ctimes10%5E%7B23%7D%29%7D%3D0%2C249%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="V_A%3D%5Cfrac%7Bn_AM_A%7D%7B%5Crho_A%7D%3D%5Cfrac%7B0%2C249%28168%29%7D%7B1%2C68%7D%3D24%2C9%5C%2C%5Cmathrm%7BL%7D" data-display="true"></span></div></div></details><details class="u6Subsolution"><summary>Muestra B · sevoflurano</summary><div><div class="u6Equation"><span class="u6Math" data-latex="M_B%3D4%2812%29%2B3%281%29%2B7%2819%29%2B16%3D200%5C%2C%5Cmathrm%7Bg%2Fmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="n_B%3D%5Cfrac%7B8%2C00%5Ctimes10%5E%7B23%7D%7D%7B7%286%2C02%5Ctimes10%5E%7B23%7D%29%7D%3D0%2C190%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="V_B%3D%5Cfrac%7Bn_BM_B%7D%7B%5Crho_B%7D%3D%5Cfrac%7B0%2C190%28200%29%7D%7B1%2C90%7D%3D20%2C0%5C%2C%5Cmathrm%7BL%7D" data-display="true"></span></div></div></details><p>Compará los volúmenes: 20,0 L &lt; 24,9 L.</p>$cbc$,$cbc$<p>Muestra B: aproximadamente 20,0 L (A: 24,9 L).</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-a',$cbc$Ejercicio 10$cbc$,$cbc$<p>Justificar la diferencia entre el punto de ebullición de la metilamina (CH₅N, Pₑᵦ = −6 °C) y de la propilamina (C₃H₉N, Pₑᵦ = 48 °C) en base a las interacciones que existen entre sus moléculas. Incluir en la justificación una explicación de por qué presentan esas interacciones. Desarrollar al dorso.</p>$cbc$,'Parcial A · fotografía recibida',100,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>En común</span><div><p>Son aminas primarias: tienen enlaces N–H y un par libre en N. Entre sus moléculas pueden formarse puentes de hidrógeno N–H···N. Además, por ser polares presentan atracciones dipolo–dipolo, y como todas las moléculas poseen fuerzas de dispersión de London.</p></div></div><div class="u6Step"><span>Diferencia</span><div><p>La propilamina tiene una cadena de carbono más larga, más electrones y mayor superficie de contacto. Su nube electrónica se polariza más: las fuerzas de London son más intensas. Se requiere más energía para separarla al hervir, por lo que su punto de ebullición es mayor.</p></div></div>$cbc$,$cbc$<p>Propilamina: 48 °C; metilamina: −6 °C. La diferencia principal entre ambas es la mayor dispersión de London de la propilamina.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 1$cbc$,$cbc$<p>Un isótopo del catión ₁₉K⁺ tiene el mismo número de neutrones que el nucleido ³⁸Cl. Indicar el número másico del ion ₁₉K⁺.</p>$cbc$,'Parcial B · fotografía recibida',110,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>El cloro tiene Z = 17; su nucleido de masa 38 tiene 21 neutrones.</p><div class="u6Equation"><span class="u6Math" data-latex="N_%7BCl%7D%3D38-17%3D21" data-display="true"></span></div></div></div><div class="u6Step"><span>2</span><div><p>El potasio tiene Z = 19. La carga positiva modifica electrones, pero no el número másico.</p><div class="u6Equation"><span class="u6Math" data-latex="A_K%3D19%2B21%3D40" data-display="true"></span></div></div></div>$cbc$,$cbc$<p>40 (⁴⁰₁₉K⁺).</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 2$cbc$,$cbc$<p>Dados los elementos: M (segundo metal alcalino térreo), T (su anión monovalente tiene 18 electrones) y R (su catión trivalente es isoelectrónico con el segundo gas noble), indicar cuál de las siguientes afirmaciones es la única correcta: (A) R es el elemento con mayor Energía de Ionización de los tres mencionados; (B) La CEE de T es (3s)² (3p)⁶; (C) T es un halógeno; (D) El ion M²⁺ es isoelectrónico con el átomo de Ar.</p>$cbc$,'Parcial B · fotografía recibida',120,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Identificar</span><div><p>M = Mg (segundo alcalinotérreo). T⁻ tiene 18 e⁻, entonces T neutro tiene 17: Cl. R³⁺ tiene 10 e⁻ como Ne (segundo gas noble), entonces R neutro tiene 13: Al.</p></div></div><div class="u6Step"><span>Revisar</span><div><p>(A) Al no supera a Cl en energía de ionización. (B) La CEE de Cl neutro es 3s² 3p⁵; 3p⁶ corresponde a Cl⁻. (D) Mg²⁺ tiene 10 electrones, como Ne, no 18 como Ar. Cl sí es halógeno.</p></div></div>$cbc$,$cbc$<p>(C) T es un halógeno.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 3$cbc$,$cbc$<p>Dados los siguientes compuestos: Br₂O₃ HBr NaBr HBrO₃ NaBrO₂ NaBrO₄. Identificar y nombrar al compuesto covalente que contiene bromo en estado de oxidación +3.</p>$cbc$,'Parcial B · fotografía recibida',130,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>En Br₂O₃, O tiene −2:</p><div class="u6Equation"><span class="u6Math" data-latex="2x%2B3%28-2%29%3D0%5Cquad%5CRightarrow%5Cquad%20x%3D%2B3" data-display="true"></span></div></div></div><div class="u6Step"><span>2</span><div><p>NaBrO₂ también tiene Br(+3), pero está formado por Na⁺ y BrO₂⁻ y es iónico. Br₂O₃ une dos no metales por enlaces covalentes.</p></div></div>$cbc$,$cbc$<p>Br₂O₃: óxido de bromo(III), o trióxido de dibromo.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 4$cbc$,$cbc$<p>Indicar para el CO₃²⁻ cuántos enlaces covalentes simples, cuántos dobles y cuántos triples presenta en su estructura de Lewis.</p>$cbc$,'Parcial B · fotografía recibida',140,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Lewis</span><div><p>En una estructura contribuyente de Lewis, C está unido a tres O: un C=O y dos C–O⁻. La carga total es −2; hay tres formas resonantes equivalentes según cuál O lleva el doble enlace.</p></div></div><div class="u6Equation"><span class="u6Math" data-latex="%5Cmathrm%7B%5B%5E%7B-%7DO-C%28%3DO%29-O%5E%7B-%7D%5D%7D" data-display="true"></span></div>$cbc$,$cbc$<p>En cada estructura de Lewis: 2 simples, 1 doble y 0 triples.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 5$cbc$,$cbc$<p>Indicar cuál de las siguientes moléculas presenta mayores ángulos de enlace según la TRePEV:</p><ol type="a"><li>NH₃ (estructura de Lewis en la foto)</li><li>CS₂ (estructura de Lewis en la foto)</li><li>CCl₄ (estructura de Lewis en la foto)</li><li>H₂O (estructura de Lewis en la foto)</li></ol><p>Justificar al dorso en base a TRePEV.</p><p class="examSourceLink"><a href="./assets/chemistry/parciales/parcial-b.png" target="_blank" rel="noopener">Ver fotografía original del parcial ↗</a></p>$cbc$,'Parcial B · fotografía recibida',150,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Dominios</span><div><p>CS₂ tiene dos zonas electrónicas en el C central (cada doble enlace cuenta como una). Es AX₂, lineal: 180°.</p></div></div><div class="u6Step"><span>Comparación</span><div><p>CCl₄ es tetraédrica (109,5°); NH₃ es piramidal (~107°); H₂O angular (~104,5°), por sus pares libres.</p></div></div>$cbc$,$cbc$<p>(b) CS₂, 180°.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 6$cbc$,$cbc$<p>Indicar cuál o cuáles de las siguientes propiedades corresponde al SCl₂: (A) presenta fuerzas intermoleculares dipolo permanente-dipolo permanente entre sus moléculas, (B) presenta enlaces de hidrógeno entre sus moléculas, (C) conduce la corriente en estado sólido, (D) presenta fuerzas intermoleculares de London entre sus moléculas.</p>$cbc$,'Parcial B · fotografía recibida',160,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Forma</span><div><p>SCl₂ tiene dos enlaces y dos pares libres sobre S: AX₂E₂, geometría angular. Los dipolos S–Cl no se cancelan, por eso es polar.</p></div></div><div class="u6Step"><span>Fuerzas</span><div><p>Presenta dipolo–dipolo y, como toda molécula, London. No posee H unido a N, O o F para formar enlaces de hidrógeno entre sus propias moléculas; como sustancia molecular no conduce en estado sólido.</p></div></div>$cbc$,$cbc$<p>(A) y (D).</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 7$cbc$,$cbc$<p>La lisina es un aminoácido cuya fórmula molecular es C₆H₁₄N₂O₂. Calcular qué masa de lisina se debe pesar para obtener 0,788 moles de átomos de N. Desarrollar al dorso.</p>$cbc$,'Parcial B · fotografía recibida',170,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>1</span><div><p>Hay dos átomos de N por molécula de lisina:</p><div class="u6Equation"><span class="u6Math" data-latex="n_%7B%5Cmathrm%7Blisina%7D%7D%3D%5Cfrac%7B0%2C788%7D%7B2%7D%3D0%2C394%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></span></div></div></div><div class="u6Step"><span>2</span><div><p>Masa molar con C=12, H=1, N=14 y O=16:</p><div class="u6Equation"><span class="u6Math" data-latex="M%3D6%2812%29%2B14%281%29%2B2%2814%29%2B2%2816%29%3D146%5C%2C%5Cmathrm%7Bg%2Fmol%7D" data-display="true"></span></div><div class="u6Equation"><span class="u6Math" data-latex="m%3D0%2C394%28146%29%3D57%2C5%5C%2C%5Cmathrm%7Bg%7D" data-display="true"></span></div></div></div>$cbc$,$cbc$<p>57,5 g de lisina.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 8$cbc$,$cbc$<p>Seleccionar la respuesta correcta. El cloruro de hidrógeno (HCl) y el bromuro de hidrógeno (HBr) tienen: a) igual porcentaje en masa de H; b) igual número de moléculas en un mol de sustancia; c) igual masa en un mol de sustancia; d) distinto número de átomos en un mol de sustancia.</p>$cbc$,'Parcial B · fotografía recibida',180,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Avogadro</span><div><p>Un mol de cualquier sustancia molecular contiene Nₐ moléculas: 6,02×10²³. Ambas moléculas tienen dos átomos, por lo que cada mol contiene también 2Nₐ átomos.</p></div></div><div class="u6Step"><span>Descartar</span><div><p>Las masas molares son diferentes porque Cl y Br tienen masas distintas; por eso difieren la masa por mol y el porcentaje en masa de H.</p></div></div>$cbc$,$cbc$<p>b) igual número de moléculas en un mol de sustancia.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 9$cbc$,$cbc$<p>Seleccionar la afirmación incorrecta: a) Si se aumenta la masa de un gas contenido en un recipiente de volumen fijo cerrado, la densidad aumentará. b) Un sistema heterogéneo no puede contener un único componente. c) 100 cm³ de un sistema homogéneo formado por agua (ρ = 1,00 g/cm³) y etanol (ρ = 0,789 g/cm³), cuya composición es 50 % m/m en agua, contienen igual masa de agua que de etanol. d) La molécula de SO₂ es triatómica.</p>$cbc$,'Parcial B · fotografía recibida',190,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Evaluar</span><div><p>(a) A volumen fijo, ρ=m/V aumenta con m. (c) 50 % m/m en agua implica masas iguales de agua y etanol; no implica volúmenes iguales. (d) SO₂ contiene tres átomos.</p></div></div><div class="u6Step"><span>Contraejemplo</span><div><p>Agua líquida y hielo forman dos fases, es decir, un sistema heterogéneo con un único componente químico: H₂O.</p></div></div>$cbc$,$cbc$<p>b) es la afirmación incorrecta.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',7,'parcial-b',$cbc$Ejercicio 10$cbc$,$cbc$<p>Indicar cuál es el éster que contiene, además, un grupo funcional hidroxilo:</p><p><em>La fotografía recibida termina en esta consigna; no aparecen las opciones.</em></p><p class="examSourceLink"><a href="./assets/chemistry/parciales/parcial-b.png" target="_blank" rel="noopener">Ver fotografía original del parcial ↗</a></p>$cbc$,'Parcial B · fotografía recibida',200,false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<div class="u6Step"><span>Reconocer el éster</span><div><p>Buscá el grupo R–C(=O)–O–R′. El oxígeno entre el carbonilo y R′ identifica la función éster.</p></div></div><div class="u6Step"><span>Reconocer el hidroxilo adicional</span><div><p>La misma molécula debe tener otro grupo –OH libre. Un ejemplo que satisface ambos criterios es el lactato de metilo: CH₃–CH(OH)–C(=O)–O–CH₃. El –OH unido al carbono central es el hidroxilo; el extremo –C(=O)–O–CH₃ es el éster.</p></div></div><p>No se puede elegir una alternativa específica porque la imagen no muestra las opciones.</p>$cbc$,$cbc$<p>Criterio: éster y –OH adicional; ejemplo: lactato de metilo.</p>$cbc$,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
commit;
